const U:i128=400_591_699_200;
const SLICES:usize=485;
const OUT:&str="computations/unaudited-codex-orbit0-k22-direct23-source-fold-2026-08-24/results_k22_direct23.json";
const IDS17_23:[&str;7]=["D17:234|R:2-3","D17:243|R:2-3","D17:324|R:2-3","D17:333|R:2-3","D17:342|R:2-3","D17:423|R:2-3","D17:432|R:2-3"];
const IDS17_32:[&str;7]=["D17:234|R:3-2","D17:243|R:3-2","D17:324|R:3-2","D17:333|R:3-2","D17:342|R:3-2","D17:423|R:3-2","D17:432|R:3-2"];
